/*
 * DEDICATED PUSH SERVICE WORKER
 * ═══════════════════════════════════════════════════════════════════════
 *
 * Dan, 2026-08-25: turning notifications on shows "Working..." for 10-15
 * seconds and then "Service worker startup timed out after 30s".
 *
 * WHY THE APP'S SERVICE WORKER COULD NOT BE USED FOR THIS
 *
 * /sw.js is generated by next-pwa and its install step runs
 * precacheAndRoute over 818 URLs. A service worker does not become
 * `activated` until install RESOLVES, which means all 818 downloads must
 * finish first. On a phone with one bar that is far longer than any
 * reasonable timeout — and if a SINGLE one of those 818 requests 404s or
 * times out, install REJECTS, the worker goes redundant, and it never
 * activates at all.
 *
 * Enrolling in push therefore sat waiting on the app's entire cache layer,
 * which is unrelated to push in every way except that both happen to be
 * service workers. Raising the timeout from 10s to 30s did not fix it and
 * could not: the worker was not slow, it was failing.
 *
 * This worker does push and nothing else. No precache, no fetch handler,
 * no routes. It installs in milliseconds and has nothing that can fail.
 *
 * SCOPE: registered at /push/ deliberately. Two registrations cannot share
 * a scope, and taking / would REPLACE the app's caching worker. A push
 * subscription works from any scope, and notifications shown from here can
 * still open any URL on the origin.
 */

const SP_PUSH_SW = 'sp-push-dedicated-v2-authenticated-rotation';

self.addEventListener('install', () => {
    // Nothing to cache. Take over immediately rather than waiting for every
    // client to close — the whole point is that enrolling works right now.
    self.skipWaiting();
});

self.addEventListener('activate', (event) => {
    event.waitUntil(self.clients.claim());
});

self.addEventListener('message', (event) => {
    if (event?.data?.type === 'SP_SKIP_WAITING') self.skipWaiting();
});

/**
 * CLOSE A BANNER THAT HAS OUTLIVED WHAT IT DESCRIBES (Dan 2026-08-30).
 *
 * A seat offer dies after three minutes. Until now nothing dismissed the
 * banner, so "A Seat Just Opened. Tap To Claim It." sat on the lock screen for
 * a seat long since given away, and tapping it landed the player on a full
 * table. From their side that is indistinguishable from a push that was never
 * theirs — the report this whole thread started with.
 *
 * DELIBERATELY NOT A TIMER. A service worker is killed whenever the browser
 * feels like it, so `setTimeout(close, threeMinutes)` is a promise the runtime
 * has no obligation to keep, and the one time it matters (phone in a pocket,
 * worker long since evicted) is exactly when it will not fire. Instead the
 * sweep runs at the two moments the worker is provably alive and already
 * looking at the notification list: when another push arrives, and when the
 * user taps one. Both are cheap — getNotifications() is a local read.
 *
 * The delivery-side TTL is the other half and does the heavier lifting: it
 * stops the push service handing over a stale offer at all. This half covers
 * the banner that was already on screen when the offer lapsed.
 */
function sweepExpiredNotifications() {
    return self.registration
        .getNotifications()
        .then((list) => {
            const now = Date.now();
            for (const n of list || []) {
                const expiresAt = n && n.data && n.data.expiresAt;
                if (typeof expiresAt === 'number' && expiresAt > 0 && expiresAt <= now) {
                    try {
                        n.close();
                    } catch (e) {
                        /* one stubborn banner must not stop the rest */
                    }
                }
            }
        })
        .catch(() => {
            /* Sweeping is a courtesy. It must never take down the push handler
               it is attached to — a thrown getNotifications() here would mean
               the notification that triggered it is never shown. */
        });
}

/**
 * TITLE CASE — the same house rule the OTHER worker applies (2026-09-07).
 *
 * Dan, 2026-08-30: "the first letter of every word should be capitalized
 * inside the push notifications." That was implemented in `worker/index.js`
 * five days after this file was forked out of it (2026-08-25, to escape a
 * next-pwa precache hang), and it was never applied here.
 *
 * The consequence is not cosmetic. This origin has TWO push-capable service
 * workers — `/sw.js` (worker/index.js) and this one at `/push/sw.js` — and a
 * device can hold a live subscription for each. On 2026-09-07 one device
 * received the Estate Digest twice at the same second: one banner Title Cased
 * by the other worker, one verbatim from here. The two renderings ARE the
 * evidence that there were two registrations. The duplicate itself is fixed in
 * `pages/api/push/rotate.js`; a device should now hold one subscription. This
 * half makes sure that whichever worker owns it renders the same way.
 *
 * The full reasoning for every rule below — the `(s)` carve-out, why there is
 * no lookbehind, and why a word containing a digit is left alone — is in
 * `worker/index.js`, which is the primary copy. The block is byte-identical in
 * both files and `__tests__/push-title-case.test.mjs` fails if they diverge
 * again.
 */
/* TITLE_CASE_SHARED_BEGIN — byte-identical in public/push/sw.js.
   `__tests__/push-title-case.test.mjs` extracts this block from BOTH files and
   fails if they differ. See the note about the fork below. */
const TITLE_CASE_WORD_START = /(^|[\s[{"'‘“-])([a-z])(?![A-Za-z0-9]*[0-9])/g;
const TITLE_CASE_BRACKET_WORD = /(^|\s)\(([a-z])(?![A-Za-z0-9]*[0-9])/g;

function toTitleCase(text) {
    if (typeof text !== 'string' || text === '') return text;
    try {
        return text
            .replace(TITLE_CASE_WORD_START, (_m, lead, letter) => lead + letter.toUpperCase())
            .replace(TITLE_CASE_BRACKET_WORD, (_m, lead, letter) => lead + '(' + letter.toUpperCase());
    } catch (e) {
        // If anything in here ever throws, the notification must still be
        // shown. Unstyled copy beats no notification.
        return text;
    }
}
/* TITLE_CASE_SHARED_END */

self.addEventListener('push', (event) => {
    let data = {};
    try {
        data = event.data ? event.data.json() : {};
    } catch (e) {
        // Some providers send plain text on a test send.
        try {
            data = { title: 'Smarter Poker', body: event.data ? event.data.text() : '' };
        } catch (e2) {
            data = { title: 'Smarter Poker', body: '' };
        }
    }

    // Older in-flight accounting payloads can contain private invoice text.
    // These markers only restrict presentation; they never establish access.
    const details = data?.data && typeof data.data === 'object' ? data.data : {};
    const accounting = data?.event === 'accounting_invoice' || details.event === 'accounting_invoice' ||
        data?.accountingNotificationId != null || details.accountingNotificationId != null ||
        (typeof data?.tag === 'string' && data.tag.startsWith('accounting:'));
    if (accounting) {
        data = {
            title: 'New Accounting Notice', body: 'Open Smarter Poker To View',
            url: data.url || '/hub/messenger', tag: data.tag || undefined, renotify: false,
            icon: '/notification-icon.png', badge: '/notification-icon.png',
            event: 'accounting_invoice', outboxId: details.outboxId ?? data.outboxId,
            accountingNotificationId: details.accountingNotificationId ?? data.accountingNotificationId,
        };
    }

    const title = toTitleCase(data.title || 'Smarter Poker');
    const url = data.url || '/hub';

    const options = {
        body: toTitleCase(data.body || ''),
        icon: data.icon || '/icons/icon-192.png',
        badge: data.badge || '/icons/icon-192.png',
        image: data.image || undefined,
        // notificationclick reads this back to decide where to go.
        // `expiresAt` (2026-08-30) is the wall-clock ms after which this banner
        // is describing something that no longer exists — a seat offer dies
        // after three minutes. sweepExpired() below reads it back.
        data: {
            url,
            event: data.event || null,
            outboxId: data.outboxId || null,
            accountingNotificationId: data.accountingNotificationId || null,
            expiresAt: typeof data.expiresAt === 'number' ? data.expiresAt : null,
        },
        vibrate: data.vibrate || [120, 60, 120],
        requireInteraction: data.requireInteraction === true,
        // CHROME TRAP: showNotification throws and displays NOTHING when
        // renotify is true without a tag. Never set renotify unconditionally.
        tag: data.tag || undefined,
        // A sender may ask for a REPLACEMENT rather than a fresh alert: an
        // expiry notice shares a tag with the offer it supersedes, and buzzing
        // twice for strictly less news is worse than not buzzing again.
        renotify: data.renotify === false ? false : data.tag ? true : undefined,
        actions: Array.isArray(data.actions) ? data.actions.slice(0, 2) : undefined,
        timestamp: data.sentAt || Date.now(),
    };

    event.waitUntil(
        // Sweep FIRST, so a stale seat-offer banner is gone before the new one
        // lands beside it. They share a tag now (the mirror trigger groups seat
        // events by table), so the OS would replace it anyway — this covers the
        // case where the new push is about a DIFFERENT table and the dead
        // banner would otherwise just sit there.
        sweepExpiredNotifications()
            .then(() => self.registration.showNotification(title, options))
            // A rejected showNotification means the OS refused these options.
            // Retry with the bare minimum rather than showing nothing at all.
            .catch(() => self.registration.showNotification(title, {
                body: options.body, data: options.data, tag: options.tag, renotify: false,
            }))
            .then(() => {
                try {
                    if (self.navigator && self.navigator.setAppBadge) {
                        if (typeof data.badgeCount === 'number') {
                            self.navigator.setAppBadge(data.badgeCount).catch(() => {});
                        } else {
                            self.navigator.setAppBadge().catch(() => {});
                        }
                    }
                } catch (e) { /* badging is a nicety */ }

                // Tell any open tab so the bell refreshes without a poll.
                return self.clients
                    .matchAll({ type: 'window', includeUncontrolled: true })
                    .then((clients) => {
                        for (const c of clients) {
                            try {
                                c.postMessage({ type: 'SP_PUSH_RECEIVED', event: data.event || null, url });
                            } catch (e) { /* one bad client must not stop the rest */ }
                        }
                    })
                    .catch(() => {});
            })
            .catch(() => {})
    );
});

self.addEventListener('notificationclick', (event) => {
    event.notification.close();
    // The second moment the worker is provably alive. Opening one banner is a
    // good time to clear any sibling that has outlived what it described.
    event.waitUntil(sweepExpiredNotifications());
    try {
        if (self.navigator && self.navigator.clearAppBadge) {
            self.navigator.clearAppBadge().catch(() => {});
        }
    } catch (e) { /* ignore */ }

    if (event.action === 'decline') return;

    const url = (event.notification.data && event.notification.data.url) || '/hub';

    const sameDestination = (a, b) => {
        try {
            const x = new URL(a, self.location.origin);
            const y = new URL(b, self.location.origin);
            return x.origin === y.origin &&
                x.pathname.replace(/\/+$/, '') === y.pathname.replace(/\/+$/, '') &&
                x.search === y.search && x.hash === y.hash;
        } catch (e) {
            return false;
        }
    };

    event.waitUntil(
        self.clients
            .matchAll({ type: 'window', includeUncontrolled: true })
            .then(async (clients) => {
                for (const c of clients) {
                    if ('focus' in c) {
                        if (url && !sameDestination(c.url, url)) {
                            if ('navigate' in c) {
                                try {
                                    const navigated = await c.navigate(url);
                                    if (navigated) return navigated.focus();
                                } catch (e) { /* open the exact destination below */ }
                            }
                            return self.clients.openWindow ? self.clients.openWindow(url) : null;
                        }
                        return c.focus();
                    }
                }
                return self.clients.openWindow ? self.clients.openWindow(url) : null;
            })
            .catch(() => null)
    );
});

/*
 * The browser can rotate a subscription without telling the page. Re-register
 * locally here. Server rotation now requires authenticated account authority;
 * a sessionless refusal waits for foreground authenticated enrollment.
 */
self.addEventListener('pushsubscriptionchange', (event) => {
    event.waitUntil(
        (async () => {
            try {
                const res = await fetch('/api/push/vapid-public-key', { credentials: 'same-origin' });
                if (!res.ok) return;
                const { key } = await res.json();
                if (!key) return;

                const padding = '='.repeat((4 - (key.length % 4)) % 4);
                const base64 = (key + padding).replace(/-/g, '+').replace(/_/g, '/');
                const raw = self.atob(base64);
                const appKey = new Uint8Array(raw.length);
                for (let i = 0; i < raw.length; i += 1) appKey[i] = raw.charCodeAt(i);

                const sub = await self.registration.pushManager.subscribe({
                    userVisibleOnly: true,
                    applicationServerKey: appKey,
                });
                const json = sub.toJSON();

                let oldKeys = null;
                try {
                    if (event.oldSubscription && typeof event.oldSubscription.toJSON === 'function') {
                        oldKeys = event.oldSubscription.toJSON().keys || null;
                    }
                } catch (e) { /* ignore */ }

                const rotationResponse = await fetch('/api/push/rotate', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({
                        oldEndpoint: (event.oldSubscription && event.oldSubscription.endpoint) || null,
                        endpoint: sub.endpoint,
                        keys: json.keys,
                        oldKeys,
                    }),
                });
                if (!rotationResponse.ok) {
                    console.warn('[push] Rotation unconfirmed; authenticated enrollment is required.');
                    return;
                }
                const outcome = await rotationResponse.json();
                const receipt = outcome && outcome.receipt;
                if (outcome.ok !== true || outcome.rotated !== true || !receipt ||
                    receipt.schema_version !== 1 || receipt.success !== true ||
                    receipt.old_endpoint !== (event.oldSubscription && event.oldSubscription.endpoint) ||
                    receipt.endpoint !== sub.endpoint || receipt.transport !== 'webpush') {
                    console.warn('[push] Rotation receipt unconfirmed; authenticated enrollment is required.');
                    return;
                }
                console.log('[push] Server confirmed subscription rotation.');
            } catch (err) {
                console.warn(`[${SP_PUSH_SW}] self-heal failed:`, err && err.message);
            }
        })()
    );
});
